.jui-reveal {
  position: relative;
  width: 264px;
  height: 300px;
  border-radius: 30px;
  overflow: hidden;
  background: #1ce9b6;
  color: #171717;
  isolation: isolate;
  box-shadow:
    0 2px 6px rgba(20, 24, 40, 0.1),
    0 18px 40px rgba(20, 24, 40, 0.16);
}
.jui-reveal-waves {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.jui-reveal-brand {
  position: absolute;
  top: 18px;
  left: 22px;
  color: #063b30;
  font-weight: 700;
  font-size: 12px;
}
.jui-reveal-sheet {
  position: absolute;
  inset: 0;
  background: light-dark(#fff, #24292e);
  border-radius: 30px;
  padding: 24px;
}
.jui-reveal-sheet h3 {
  font-size: 20px;
  line-height: 1.18;
  margin: 12px 0;
}
.jui-reveal-sheet p {
  font-size: 12.5px;
  line-height: 1.55;
  color: light-dark(#686868, #b4bbc3);
  margin: 9px 0;
}
.jui-reveal-action {
  margin-top: 14px;
}
.jui-reveal-action a,
.jui-reveal-action button {
  display: inline-block;
  padding: 7px 14px;
  border: 0;
  border-radius: 999px;
  background: #063b30;
  color: #fff;
  font: inherit;
  font-size: 12px;
  text-decoration: none;
}

.jui-reveal-sheet {
  color: light-dark(#171717, #f3f5f6);
}

"use client";
import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { RippleField } from "@/components/ui/ripple-field";
import "./reveal-card.css";
export type RevealCardProps = Omit<ComponentProps<"article">, "title"> & {
  title: ReactNode;
  brand?: ReactNode;
  action?: ReactNode;
  background?: ReactNode;
};
export function RevealCard({
  title,
  brand,
  action,
  background,
  children,
  className,
  ...props
}: RevealCardProps) {
  const reduced = useReducedMotion();
  return (
    <article
      {...props}
      data-slot="reveal-card"
      className={cn("jui-reveal", className)}
    >
      {background ?? <RippleField className="jui-reveal-waves" />}
      {brand && <span className="jui-reveal-brand">{brand}</span>}
      <motion.div
        className="jui-reveal-sheet"
        initial={reduced ? false : { y: 0 }}
        whileInView={{ y: "20%" }}
        viewport={{ once: true, amount: 0.6 }}
        transition={{ duration: reduced ? 0 : 0.66, ease: [0.16, 1, 0.3, 1] }}
      >
        <h3>{title}</h3>
        <motion.div
          initial={reduced ? false : { opacity: 0, filter: "blur(7px)", y: 7 }}
          whileInView={{ opacity: 1, filter: "blur(0px)", y: 0 }}
          viewport={{ once: true }}
          transition={{
            duration: reduced ? 0 : 0.55,
            delay: reduced ? 0 : 0.3,
          }}
        >
          {children}
          {action && <div className="jui-reveal-action">{action}</div>}
        </motion.div>
      </motion.div>
    </article>
  );
}

"use client";
import { useEffect, useRef, type ComponentProps } from "react";
import { cn } from "@/lib/utils";
export type RippleFieldProps = ComponentProps<"svg"> & {
  lines?: number;
  width?: number;
  height?: number;
};
export function RippleField({
  stroke = "#2f7bd4",
  lines = 12,
  width = 264,
  height = 300,
  className,
  ...props
}: RippleFieldProps) {
  const ref = useRef<SVGSVGElement>(null);
  useEffect(() => {
    const svg = ref.current;
    if (!svg) return;
    const count = Math.max(2, Math.min(100, Math.round(lines)));
    const paths = Array.from({ length: count }, (_, i) => {
      const p = document.createElementNS("http://www.w3.org/2000/svg", "path");
      p.setAttribute("opacity", String(Math.max(0.1, 0.85 - i * 0.02)));
      svg.appendChild(p);
      return p;
    });
    const media = matchMedia("(prefers-reduced-motion: reduce)");
    let raf = 0;
    let started = 0;
    const wave = (x: number, l: number, t: number) =>
      7 * Math.sin(0.024 * x + t * 0.75 + l * 0.55) +
      4.5 * Math.sin(0.013 * x - t * 0.5 + l * 0.935) +
      2.6 * Math.sin(0.045 * x + t * 1.2 + l * 0.22) +
      1.8 * Math.sin(0.08 * x - t * 0.95);
    const draw = (now: number) => {
      started ||= now;
      const t = media.matches ? 0 : (now - started) / 1000;
      paths.forEach((p, i) => {
        let d = "";
        for (let x = -10; x <= width + 10; x += 8)
          d += `${x === -10 ? "M" : "L"} ${x} ${((i * height) / (count - 1) + wave(x, i, t)).toFixed(2)} `;
        p.setAttribute("d", d);
      });
      if (!media.matches && !document.hidden) raf = requestAnimationFrame(draw);
    };
    const restart = () => {
      cancelAnimationFrame(raf);
      draw(performance.now());
    };
    restart();
    media.addEventListener("change", restart);
    document.addEventListener("visibilitychange", restart);
    return () => {
      cancelAnimationFrame(raf);
      paths.forEach((p) => p.remove());
      media.removeEventListener("change", restart);
      document.removeEventListener("visibilitychange", restart);
    };
  }, [lines, width, height]);
  return (
    <svg
      aria-hidden="true"
      {...props}
      ref={ref}
      data-slot="ripple-field"
      className={cn(className)}
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      fill="none"
      stroke={stroke}
      strokeWidth="1.8"
      strokeLinecap="round"
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
